6	using System.Text.Json.Nodes;
7	
8	namespace Cordango.SourceGen.DotNetVue.Model;
9	
10	/// <summary>
11	/// The compiled manifest, read once into shapes the emitters can use.
12	///
13	/// <para><b>Read from the MANIFEST, never from the definition.</b> The two look alike and are not
14	/// the same document: the manifest is what the compiler produced — base fields prepended, defaults
15	/// filled, options coloured, processes canonicalised, commands synthesized from transitions, views
16	/// and pages invented where the author wrote none. An emitter reading the definition would generate
17	/// an application missing everything the compiler decided, and would do it silently, because the
18	/// definition is also a valid document.</para>
19	///
