using Cordango.Definition;

namespace Cordango.Compiler.Tests;

public class ZZProbeTests
{
    private static ComputedValueKind Kind(string key) => key switch
    {
        "flag" => ComputedValueKind.Boolean,
        "other" => ComputedValueKind.Boolean,
        _ => ComputedValueKind.Number,
    };

    private static ComputedValue? Ev(string expr, decimal? a = null, decimal? b = null,
        bool? flag = null, bool? other = null) =>
        ComputedExpr.EvaluateValue(expr, Kind,
            key => key switch { "a" => a, "b" => b, _ => null },
            key => key switch { "flag" => flag, "other" => other, _ => null });

    [Fact]
    public void Probe()
    {
        void Say(string label, ComputedValue? v) =>
            Console.WriteLine($"PROBE {label,-42} => kind={v?.Kind.ToString() ?? "<null>"} num={v?.Number?.ToString() ?? "null"} bool={v?.Boolean?.ToString() ?? "null"}");

        // comparisons with an unknown operand
        Say("a < b   (a=null,b=null)", Ev("a < b"));
        Say("a < b   (a=1,b=2)", Ev("a < b", a: 1, b: 2));

        // divide-by-zero feeding a comparison
        Say("(a / b) < 1  (a=1,b=0)", Ev("(a / b) < 1", a: 1, b: 0));

        // boolean logic over an unknown comparison
        Say("not ((a / b) < 1)  (a=1,b=0)", Ev("not ((a / b) < 1)", a: 1, b: 0));
        Say("((a / b) < 1) and true  (a=1,b=0)", Ev("((a / b) < 1) and true", a: 1, b: 0));
        Say("((a / b) < 1) or false  (a=1,b=0)", Ev("((a / b) < 1) or false", a: 1, b: 0));
        Say("((a/b)<1) == ((a/b)<1) (a=1,b=0)", Ev("((a / b) < 1) == ((a / b) < 1)", a: 1, b: 0));

        // blank boolean field
        Say("flag            (flag=null)", Ev("flag"));
        Say("flag and true   (flag=null)", Ev("flag and true"));
        Say("flag == other   (both null)", Ev("flag == other"));
        Say("not flag        (flag=null)", Ev("not flag"));

        // blank number reads as zero
        Say("a + 1           (a=null)", Ev("a + 1"));
        Say("a == 0          (a=null)", Ev("a == 0"));
    }
}
EOF
