using System.Text.Json.Nodes;
using Cordango.SourceGen.DotNetVue.Emit;
using Cordango.SourceGen.DotNetVue.Model;

namespace Cordango.Standalone.Tests;

public class ZZEmitProbeTests
{
    private static EntityModel Entity() => new(new JsonObject
    {
        ["key"] = "row",
        ["label"] = "Row",
        ["fields"] = new JsonArray(
            new JsonObject { ["key"] = "a", ["label"] = "A", ["type"] = "decimal" },
            new JsonObject { ["key"] = "b", ["label"] = "B", ["type"] = "decimal" },
            new JsonObject { ["key"] = "flag", ["label"] = "Flag", ["type"] = "boolean" },
            new JsonObject { ["key"] = "other", ["label"] = "Other", ["type"] = "boolean" },
            new JsonObject { ["key"] = "result", ["label"] = "Result", ["type"] = "boolean" })
    }, "Probe");

    [Theory]
    [InlineData("a < b")]
    [InlineData("(a / b) < 1")]
    [InlineData("not ((a / b) < 1)")]
    [InlineData("((a / b) < 1) and true")]
    [InlineData("((a / b) < 1) or false")]
    [InlineData("((a / b) < 1) == ((a / b) < 1)")]
    [InlineData("flag and other")]
    [InlineData("not flag")]
    [InlineData("flag == other")]
    [InlineData("a < b and flag")]
    public void Probe(string expr)
    {
        var entity = Entity();
        var field = new FieldModel(new JsonObject
        {
            ["key"] = "result",
            ["label"] = "Result",
            ["type"] = "boolean",
            ["computed"] = new JsonObject { ["expr"] = expr },
        }, "row");

        var emitted = ComputedEmitter.Expression(entity, field);
        Console.WriteLine($"EMIT {expr,-34} => {emitted ?? "<REFUSED>"}");
    }
}
EOF
