{
    public static bool? Compare(decimal? l, decimal? r, string op) => null;
    // exactly what the emitter produces for `((a / b) < 1) and true`
    public static bool? AndCase(decimal? a, decimal? b) => (Compare(a / b, 1m, "<") && true);
    // and for `... or false`
    public static bool? OrCase(decimal? a, decimal? b) => (Compare(a / b, 1m, "<") || false);
    // and for `not ((a / b) < 1)` — this one is a lifted operator and should compile
    public static bool? NotCase(decimal? a, decimal? b) => !Compare(a / b, 1m, "<");
}
