public static class Calc
{
    public static decimal? Divide(decimal? l, decimal? r) => r is null or 0m ? null : l / r;
    public static bool? Compare(decimal? l, decimal? r, string op) => null;
    public static bool? Same(bool? l, bool? r) => l is { } a && r is { } b ? a == b : null;
    public static bool? Different(bool? l, bool? r) => l is { } a && r is { } b ? a != b : null;
}
public sealed class Row { public decimal? Costs { get; set; } public long? Months { get; set; } public decimal? Threshold { get; set; } public bool? Active { get; set; } public bool? Archived { get; set; } }
public static class RowComputed
{
    // exactly what ComputedEmitter now writes for each fixture-05 shape
    public static bool? AndTrue(Row r) => (Calc.Compare(Calc.Divide((r.Costs ?? 0m), (r.Months ?? 0m)), (r.Threshold ?? 0m), "<") & (r.Active ?? false));
    public static bool? OrTrue(Row r)  => (Calc.Compare(Calc.Divide((r.Costs ?? 0m), (r.Months ?? 0m)), (r.Threshold ?? 0m), "<") | (r.Active ?? false));
    public static bool? NotCmp(Row r)  => !Calc.Compare(Calc.Divide((r.Costs ?? 0m), (r.Months ?? 0m)), (r.Threshold ?? 0m), "<");
    public static bool? SameCmp(Row r) => Calc.Same(Calc.Compare((r.Costs ?? 0m), (r.Threshold ?? 0m), "<"), Calc.Compare((r.Costs ?? 0m), (r.Threshold ?? 0m), "<"));
    public static bool? PlainBools(Row r) => ((r.Active ?? false) & (r.Archived ?? false));
    public static bool? Nested(Row r) => !((Calc.Compare(Calc.Divide((r.Costs ?? 0m), (r.Months ?? 0m)), (r.Threshold ?? 0m), "<") & (r.Active ?? false)));
}
