    // always read as a number: the Gate has already refused a hop to anything else in an
    // arithmetic position, so treating it as numeric here cannot mask an authoring mistake.
    ComputedValueKind? Kind(string key) => key.Contains('.') ? ComputedValueKind.Number
        : fields.TryGetValue(key, out var field)
        ? FieldType(field) == "boolean" ? ComputedValueKind.Boolean
        : FieldType(field) is "integer" or "decimal" or "money" ? ComputedValueKind.Number
        : FieldType(field) is "date" or "datetime" ? ComputedValueKind.Date
        : null
        : null;

    void Compute(string key)
    {
        if (state.GetValueOrDefault(key) == 2) return;
        if (state.GetValueOrDefault(key) == 1) { rec[key] = null; return; }
        state[key] = 1;
        var expr = expressions[key];
        // LOCAL identifiers only: a field named inside prev() is read off the PREVIOUS row, so it
        // is not a dependency here — and counting it as one makes every recurrence self-referential.
        foreach (var dependency in ComputedExpr.LocalIdentifiers(expr))
            if (expressions.ContainsKey(dependency)) Compute(dependency);

        JsonNode? Read(string id) => id.Contains('.') ? hop?.Invoke(id) : rec[id];
        var value = ComputedExpr.EvaluateValue(expr, Kind,
            id => NumValue(Read(id)), id => BoolValue(Read(id)), id => DateValue(Read(id)), prev);
        rec[key] = value is { Kind: ComputedValueKind.Boolean }
            ? value.Value.Boolean is { } boolean ? JsonValue.Create(boolean) : null
            : ToFieldNumber(fields[key], value?.Number);
        state[key] = 2;
    }

    foreach (var key in expressions.Keys) Compute(key);
}

/// <summary>The timestamp value of a date/datetime field for a duration function (hours_between…).
/// Parses an ISO date or datetime; a blank/unparseable value is null, which makes the whole duration
/// null (an open ticket has no time-to-close, so it drops out of an average rather than reading 0).</summary>
private static DateTimeOffset? DateValue(JsonNode? node)
{
    if (node is not JsonValue v || !v.TryGetValue<string>(out var s) || string.IsNullOrWhiteSpace(s)) return null;
    return DateTimeOffset.TryParse(s, CultureInfo.InvariantCulture,
        DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out var dt) ? dt : null;

