66	                        + $"boolean={Show(actual.Value.Boolean)}.\n{where}");
67	                    break;
68	
69	                case JsonValue flag when flag.GetValueKind() is JsonValueKind.True or JsonValueKind.False:
70	                    var wantBool = flag.GetValue<bool>();
71	                    Assert.True(actual!.Value.Kind == ComputedValueKind.Boolean,
72	                        $"expected a boolean, but the expression is statically {actual.Value.Kind}.\n{where}");
