                root, "api", "bin", "Release", "net10.0", Namespace + ".Api.dll"));

            var entity = assembly.GetType($"{Namespace}.Entities.Row", throwOnError: true)!;
            var computedType = assembly.GetType($"{Namespace}.Computed.RowComputed", throwOnError: true)!;

