            "decimal" or "money" => value.GetValue<decimal>(),
            "boolean" => value.GetValue<bool>(),
            "date" => DateOnly.ParseExact(value.GetValue<string>(), "yyyy-MM-dd", CultureInfo.InvariantCulture),
