using Cordango.Definition;

namespace AppBuilder.Runtime;

/// <summary>A typed computed result. A numeric result may be null when its inputs cannot produce a
/// trustworthy number (for example division by zero or an unset duration endpoint).</summary>
public readonly record struct ComputedValue(
    ComputedValueKind Kind, decimal? Number, bool? Boolean, DateTimeOffset? Date)
{
    public static ComputedValue FromNumber(decimal? value) => new(ComputedValueKind.Number, value, null, null);
    public static ComputedValue FromBoolean(bool? value) => new(ComputedValueKind.Boolean, null, value, null);
    public static ComputedValue FromDate(DateTimeOffset? value) => new(ComputedValueKind.Date, null, null, value);
}

/// <summary>
/// Working out what a computed expression COMES TO, over one record.
///
/// <para><b>Why this is here and not in the compiler.</b> The line is the job, not the feature: the
/// CLI turns an expression into source code, and the platform turns one into a value. Those are
/// different components that happen to share a grammar. <c>Cordango.Compiler</c> keeps the grammar,
/// the parser, the typed AST and the author-time validation, because a person writing an application
/// has to be told their expression is wrong whether or not they ever run it here — and because a
/// generator in any language needs the tree to translate. What it does not need, and no longer
/// carries, is an interpreter.</para>
///
/// <para>So there is one grammar and two consumers of it. A standalone application built by the CLI
/// has arithmetic compiled into it and never sees this class. Every figure on the platform comes
/// through here.</para>
///
/// <para><b>The two of them must agree, and that is pinned as data rather than trusted.</b>
/// <c>tests/fixtures/computed/</c> in the Cordango repository is a specification both sides are
/// asserted against: this evaluator by the suite beside it, and the emitted C# by
/// <c>GeneratedComputedTests</c>, which builds a real application and runs it. Hand-written, never
/// recorded from either — recording would make one of them the definition of correct and enshrine
/// its bugs as the contract the other has to match.</para>
///
/// <para><b>The rule underneath all of it: a blank field is zero, and unknown is not.</b> A record
/// with no tax has a tax of nothing, so a blank NUMBER reads as zero and a blank BOOLEAN reads as
/// false — a total that refused to add them up would be empty on every half-filled row. But a figure
/// that could not be WORKED OUT — divided by zero, bounded by something unknown, raised to a power
/// that overflows — is unknown, and it stays unknown through everything downstream, boolean
/// operators included.</para>
/// </summary>
public static class ComputedEval
{
    /// <summary>Compatibility entry point for numeric-only callers.</summary>
    public static decimal? Evaluate(string? expr, Func<string, decimal?> value,
        Func<string, DateTimeOffset?>? dateValue = null) =>
        EvaluateValue(expr, _ => ComputedValueKind.Number, value, _ => null, dateValue)?.Number;

    /// <summary>Evaluate a statically typed expression over one record. Invalid expressions return
    /// null and should only be possible when an unvalidated manifest reaches the runtime.</summary>
    /// <param name="prevValue">The same field on the PREVIOUS row of an ordered series, or null when
    /// there is none. Null itself (no resolver) means this caller has no series, and every
    /// <c>prev()</c> falls back to its seed.</param>
    public static ComputedValue? EvaluateValue(string? expr,
        Func<string, ComputedValueKind?> fieldKind,
        Func<string, decimal?> numberValue,
        Func<string, bool?> booleanValue,
        Func<string, DateTimeOffset?>? dateValue = null,
        Func<string, decimal?>? prevValue = null)
    {
        var node = ComputedExpr.Parse(expr, fieldKind);
        if (node is null) return null;
        return Eval(node, numberValue, booleanValue, dateValue ?? (_ => null), prevValue);
    }

    private static ComputedValue Eval(ComputedExpr.Node node,
        Func<string, decimal?> numberValue,
        Func<string, bool?> booleanValue,
        Func<string, DateTimeOffset?> dateValue,
        Func<string, decimal?>? prevValue = null)
    {
        decimal? Num(ComputedExpr.Node n) => Eval(n, numberValue, booleanValue, dateValue, prevValue).Number;
        DateTimeOffset? Date(ComputedExpr.Node n) => Eval(n, numberValue, booleanValue, dateValue, prevValue).Date;

        // NULLABLE, and that is the whole of it.
        //
        // This used to be `.Boolean == true`, which turned "nobody knows" into "no" at the first
        // boolean operator it met. `Compare` was careful to answer null for a comparison it could not
        // make, and then `not`, `and`, `or` and `==` threw that away — so `not ((a / b) < 1)` on a
        // record where b is blank answered TRUE, having quietly decided that a figure nobody could
        // work out was below the threshold.
        //
        // A blank FIELD still reads as false, exactly as a blank number reads as zero: see the
        // FieldNode arms below. What propagates is the other kind of missing.
        bool? Truth(ComputedExpr.Node n) => Eval(n, numberValue, booleanValue, dateValue, prevValue).Boolean;

        return node switch
        {
            ComputedExpr.NumberNode n => ComputedValue.FromNumber(n.Value),
            ComputedExpr.BooleanNode b => ComputedValue.FromBoolean(b.Value),
            ComputedExpr.FieldNode f when f.Kind == ComputedValueKind.Number =>
                ComputedValue.FromNumber(numberValue(f.Key) ?? 0m),
            ComputedExpr.FieldNode f when f.Kind == ComputedValueKind.Boolean =>
                ComputedValue.FromBoolean(booleanValue(f.Key) ?? false),
            ComputedExpr.FieldNode f => ComputedValue.FromDate(dateValue(f.Key)),

            ComputedExpr.UnaryNode { Op: "-" } u => ComputedValue.FromNumber(-Num(u.Operand)),

            // `!` on `bool?` is already the rule we want: the negation of something nobody knows is
            // still something nobody knows.
            ComputedExpr.UnaryNode u => ComputedValue.FromBoolean(!Truth(u.Operand)),

            ComputedExpr.BinaryNode { Op: "+" } b => ComputedValue.FromNumber(Num(b.Left) + Num(b.Right)),
            ComputedExpr.BinaryNode { Op: "-" } b => ComputedValue.FromNumber(Num(b.Left) - Num(b.Right)),
            ComputedExpr.BinaryNode { Op: "*" } b => ComputedValue.FromNumber(Num(b.Left) * Num(b.Right)),
            ComputedExpr.BinaryNode { Op: "/" } b => Divide(Num(b.Left), Num(b.Right)),

            ComputedExpr.BinaryNode { Op: "<", Left.Kind: ComputedValueKind.Date } b =>
                Compare(Date(b.Left), Date(b.Right), (a, c) => a < c),
            ComputedExpr.BinaryNode { Op: "<=", Left.Kind: ComputedValueKind.Date } b =>
                Compare(Date(b.Left), Date(b.Right), (a, c) => a <= c),
            ComputedExpr.BinaryNode { Op: ">", Left.Kind: ComputedValueKind.Date } b =>
                Compare(Date(b.Left), Date(b.Right), (a, c) => a > c),
            ComputedExpr.BinaryNode { Op: ">=", Left.Kind: ComputedValueKind.Date } b =>
                Compare(Date(b.Left), Date(b.Right), (a, c) => a >= c),

            ComputedExpr.BinaryNode { Op: "<" } b => Compare(Num(b.Left), Num(b.Right), (a, c) => a < c),
            ComputedExpr.BinaryNode { Op: "<=" } b => Compare(Num(b.Left), Num(b.Right), (a, c) => a <= c),
            ComputedExpr.BinaryNode { Op: ">" } b => Compare(Num(b.Left), Num(b.Right), (a, c) => a > c),
            ComputedExpr.BinaryNode { Op: ">=" } b => Compare(Num(b.Left), Num(b.Right), (a, c) => a >= c),

            ComputedExpr.BinaryNode { Op: "==", Left.Kind: ComputedValueKind.Number } b =>
                Compare(Num(b.Left), Num(b.Right), (a, c) => a == c),
            ComputedExpr.BinaryNode { Op: "!=", Left.Kind: ComputedValueKind.Number } b =>
                Compare(Num(b.Left), Num(b.Right), (a, c) => a != c),
            ComputedExpr.BinaryNode { Op: "==", Left.Kind: ComputedValueKind.Date } b =>
                Compare(Date(b.Left), Date(b.Right), (a, c) => a == c),
            ComputedExpr.BinaryNode { Op: "!=", Left.Kind: ComputedValueKind.Date } b =>
                Compare(Date(b.Left), Date(b.Right), (a, c) => a != c),

            // Written out rather than using `==` on two `bool?`, because C#'s lifted equality is not
            // the rule we want: it answers TRUE for null == null and FALSE for null == true, which is
            // two-valued logic wearing a nullable type. Two things nobody knows are not thereby equal.
            ComputedExpr.BinaryNode { Op: "==" } b =>
                ComputedValue.FromBoolean(SameTruth(Truth(b.Left), Truth(b.Right))),
            ComputedExpr.BinaryNode { Op: "!=" } b =>
                ComputedValue.FromBoolean(DifferentTruth(Truth(b.Left), Truth(b.Right))),

            // `&` and `|` rather than `&&` and `||`: on `bool?` these ARE three-valued logic, and they
            // keep the answers that are still definite. Unknown AND false is false whatever the
            // unknown turns out to be; unknown OR true is true. Only where the unknown could change
            // the answer does the answer become unknown.
            ComputedExpr.BinaryNode { Op: "and" } b =>
                ComputedValue.FromBoolean(Truth(b.Left) & Truth(b.Right)),
            ComputedExpr.BinaryNode { Op: "or" } b =>
                ComputedValue.FromBoolean(Truth(b.Left) | Truth(b.Right)),

            ComputedExpr.FunctionNode { Name: "pow" } f =>
                ComputedValue.FromNumber(Power(Num(f.Left), Num(f.Right))),
            ComputedExpr.FunctionNode { Name: "min" } f =>
                ComputedValue.FromNumber(Bound(Num(f.Left), Num(f.Right), lower: true)),
            ComputedExpr.FunctionNode { Name: "max" } f =>
                ComputedValue.FromNumber(Bound(Num(f.Left), Num(f.Right), lower: false)),

            ComputedExpr.DurationNode d =>
                ComputedValue.FromNumber(Duration(d.Name, dateValue(d.From), dateValue(d.To))),

            // No previous row → the seed, or zero. `prevValue` returning null means "there is no
            // previous row"; a previous row whose field is blank also reads as the seed, which is the
            // same thing for a running total.
            ComputedExpr.PrevNode p => ComputedValue.FromNumber(prevValue?.Invoke(p.Field)
                ?? (p.Seed is null ? 0m : Num(p.Seed))),

            _ => ComputedValue.FromNumber(null),
        };
    }

    /// <summary>Division, the one arithmetic operator that can fail to have an answer. <c>x / 0</c> is
    /// neither zero nor an exception: it is unknown. A runway of "cash divided by monthly burn" on a
    /// plan with no costs yet is not infinite and not zero — nobody knows it.</summary>
    private static ComputedValue Divide(decimal? left, decimal? right) =>
        ComputedValue.FromNumber(right is null or 0m ? null : left / right);

    private static ComputedValue Compare(decimal? left, decimal? right, Func<decimal, decimal, bool> compare) =>
        ComputedValue.FromBoolean(left is { } a && right is { } b ? compare(a, b) : null);

    private static ComputedValue Compare(DateTimeOffset? left, DateTimeOffset? right,
        Func<DateTimeOffset, DateTimeOffset, bool> compare) =>
        ComputedValue.FromBoolean(left is { } a && right is { } b ? compare(a, b) : null);

    /// <summary>Equality that keeps "cannot say" separate from "no". Two unknowns are not equal —
    /// they are two things nobody knows. Mirrors <c>Calc.Same</c> in the standalone runtime, which a
    /// generated application calls for the same operator.</summary>
    private static bool? SameTruth(bool? left, bool? right) =>
        left is { } a && right is { } b ? a == b : null;

    private static bool? DifferentTruth(bool? left, bool? right) =>
        left is { } a && right is { } b ? a != b : null;

    private static decimal? Duration(string name, DateTimeOffset? from, DateTimeOffset? to)
    {
        if (from is not { } a || to is not { } b) return null;
        var span = b - a;
        return name switch
        {
            "minutes_between" => (decimal)span.TotalMinutes,
            "hours_between" => (decimal)span.TotalHours,
            "days_between" => (decimal)span.TotalDays,
            _ => null,
        };
    }

    /// <summary>The lower or upper of two values. Null in, null out — a bound that could not be
    /// worked out is not the same as no bound, and returning the other side would silently un-cap the
    /// figure.</summary>
    private static decimal? Bound(decimal? left, decimal? right, bool lower)
    {
        if (left is not { } a || right is not { } b) return null;
        return lower ? Math.Min(a, b) : Math.Max(a, b);
    }

    /// <summary>Raising to a power, through <c>double</c> because <c>decimal</c> has no power
    /// operator — and back through a checked conversion, because the round trip can overflow and an
    /// OverflowException from inside a total is a 500 on a page somebody was only reading.</summary>
    private static decimal? Power(decimal? b, decimal? e)
    {
        if (b is not { } bv || e is not { } ev) return null;
        var result = Math.Pow((double)bv, (double)ev);
        if (double.IsNaN(result) || double.IsInfinity(result)) return null;
        try { return (decimal)result; } catch (OverflowException) { return null; }
    }
}

