using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using Cordango.Definition;

namespace AppBuilder.Runtime.Tests;

/// <summary>
/// This evaluator against the computed figure fixtures in the Cordango repository.
///
/// <para>Same arrangement as <see cref="ConditionFixtureTests"/>, with one difference worth knowing:
/// the other implementation of these rules is not another evaluator. It is SOURCE CODE. The CLI turns
/// a computed expression into a C# method compiled into the application it generates, and its suite
/// proves that method returns these answers by building a real application and running it.</para>
///
/// <para>So: one specification, two things held to it — this, which works a figure out over a record,
/// and the arithmetic the generator writes. Hand-written, never recorded from either side; recording
/// would make one of them the definition of correct and enshrine its bugs as the contract the other
/// has to match.</para>
///
/// <para>If a case here fails, the interesting question is which side moved. Run
/// <c>dotnet test oss/cordango/Cordango.slnx</c> too: both failing means the fixture is wrong, one
/// failing means an implementation is.</para>
/// </summary>
public class ComputedFixtureTests
{
    public static TheoryData<string> Fixtures()
    {
        var data = new TheoryData<string>();
        foreach (var path in Directory.EnumerateFiles(FixtureDirectory, "*.json")
                     .OrderBy(p => p, StringComparer.Ordinal))
            data.Add(Path.GetFileName(path));
        return data;
    }

    [Theory]
    [MemberData(nameof(Fixtures))]
    public void Figures_match_the_fixture(string fileName)
    {
        var fixture = JsonNode.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, fileName)))!.AsObject();
        var name = fixture["name"]?.GetValue<string>() ?? fileName;
        var fields = fixture["fields"]!.AsObject();

        var cases = fixture["cases"]!.AsArray();
        Assert.NotEmpty(cases);

        for (var i = 0; i < cases.Count; i++)
        {
            var scenario = cases[i]!.AsObject();
            var record = scenario["record"]!.AsObject();
            var expr = scenario["expr"]!.GetValue<string>();
            var expected = scenario["expect"];

            var why = scenario["why"]?.GetValue<string>();
            var where = $"{fileName} case {i} ({name})"
                + (why is null ? "" : $"\n  {why}")
                + $"\n  expr:   {expr}"
                + $"\n  record: {record.ToJsonString()}";

            var actual = ComputedEval.EvaluateValue(
                expr,
                key => Kind(fields, key),
                key => Number(record, key),
                key => Boolean(record, key),
                key => Date(record, key));

            Assert.True(actual is not null,
                "the evaluator could not parse this expression at all, which means the fixture names "
                + $"something the language does not have.\n{where}");

            switch (expected)
            {
                case null:
                    // Unknown. Which of the two slots carries it depends on the expression's static
                    // type, and both must be empty for the answer to be "nobody knows".
                    Assert.True(actual!.Value.Number is null && actual.Value.Boolean is null,
                        $"expected unknown, got number={Show(actual.Value.Number)} "
                        + $"boolean={Show(actual.Value.Boolean)}.\n{where}");
                    break;

                case JsonValue flag when flag.GetValueKind() is JsonValueKind.True or JsonValueKind.False:
                    var wantBool = flag.GetValue<bool>();
                    Assert.True(actual!.Value.Kind == ComputedValueKind.Boolean,
                        $"expected a boolean, but the expression is statically {actual.Value.Kind}.\n{where}");
                    Assert.True(wantBool == actual.Value.Boolean,
                        $"expected {wantBool}, got {Show(actual.Value.Boolean)}.\n{where}");
                    break;

                case JsonValue number:
                    var wantNumber = number.GetValue<decimal>();
                    Assert.True(actual!.Value.Kind == ComputedValueKind.Number,
                        $"expected a number, but the expression is statically {actual.Value.Kind}.\n{where}");
                    Assert.True(wantNumber == actual.Value.Number,
                        $"expected {wantNumber}, got {Show(actual.Value.Number)}.\n{where}");
                    break;

                default:
                    Assert.Fail($"`expect` must be a number, true, false, or null.\n{where}");
                    break;
            }
        }
    }

    /// <summary>
    /// Guards the guard. An empty fixture directory would leave this class green while checking
    /// nothing — and the submodule not being checked out is exactly how that happens here.
    /// </summary>
    [Fact]
    public void The_fixtures_are_actually_there()
    {
        Assert.True(Directory.Exists(FixtureDirectory),
            $"{FixtureDirectory} does not exist. The Cordango submodule is not checked out, and without "
            + "it nothing holds this evaluator and the generated arithmetic to the same answers.");

        var files = Directory.GetFiles(FixtureDirectory, "*.json");
        Assert.True(files.Length >= 5,
            $"Expected the computed figure fixtures in {FixtureDirectory}; found {files.Length} files.");
    }

    private static ComputedValueKind? Kind(JsonObject fields, string key) =>
        fields[key]?["type"]?.GetValue<string>() switch
        {
            "boolean" => ComputedValueKind.Boolean,
            "date" or "datetime" => ComputedValueKind.Date,
            _ => ComputedValueKind.Number,
        };

    // A key the record does not carry is a field nobody has filled in, which is the whole subject of
    // these files. It reads as null HERE; turning that into a zero is the evaluator's job, and doing
    // it in this reader would make the test assert the evaluator agrees with itself.

    private static decimal? Number(JsonObject record, string key) =>
        record[key] is JsonValue v && v.TryGetValue<decimal>(out var d) ? d : null;

    private static bool? Boolean(JsonObject record, string key) =>
        record[key] is JsonValue v && v.TryGetValue<bool>(out var b) ? b : null;

    /// <summary>A plain <c>date</c> is read at midnight UTC, which keeps "two days" meaning two days
    /// rather than one and a bit.</summary>
    private static DateTimeOffset? Date(JsonObject record, string key) =>
        record[key] is JsonValue v && v.TryGetValue<string>(out var s) && s.Length > 0
            ? DateTimeOffset.Parse(s, CultureInfo.InvariantCulture,
                DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal)
            : null;

    private static string Show(decimal? value) =>
        value?.ToString(CultureInfo.InvariantCulture) ?? "unknown";

    private static string Show(bool? value) => value?.ToString() ?? "unknown";

    private static string FixtureDirectory =>
        Path.Combine(PlatformRoot(), "oss", "cordango", "tests", "fixtures", "computed");

    private static string PlatformRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !Directory.Exists(Path.Combine(dir.FullName, "backend")))
            dir = dir.Parent;

        return dir?.FullName
            ?? throw new InvalidOperationException(
                "Could not find the repository root above " + AppContext.BaseDirectory + ".");
    }
}

