using System.Reflection;

namespace AppBuilder.Api.Tests;

public class OssBoundaryTests
{
    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !Directory.Exists(Path.Combine(dir.FullName, "backend")))
            dir = dir.Parent;
        Assert.True(dir is not null, "could not locate the repository root");
        return dir!.FullName;
    }

    private static string OssRoot() => Path.Combine(RepoRoot(), "oss");

    private static IEnumerable<string> OssProjects() =>
        Directory.Exists(OssRoot())
            ? Directory.GetFiles(OssRoot(), "*.csproj", SearchOption.AllDirectories)
                .Where(p => !p.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}")
                         && !p.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}"))
            : [];

    [Fact]
    public void The_submodules_are_checked_out()
    {
        Assert.True(File.Exists(Path.Combine(OssRoot(), "cordango", "schemas", "app-definition.schema.json")),
            "oss/cordango looks empty — the submodule is not checked out");
        Assert.NotEmpty(OssProjects());
    }

    [Fact]
    public void No_open_source_project_reaches_back_into_the_platform()
    {
        var offenders = new List<string>();
        foreach (var p in OssProjects())
        {
            var text = File.ReadAllText(p);
            if (text.Contains("backend\\", StringComparison.OrdinalIgnoreCase)
                || text.Contains("backend/", StringComparison.OrdinalIgnoreCase)
                || text.Contains("AppBuilder.", StringComparison.Ordinal))
                offenders.Add(Path.GetRelativePath(RepoRoot(), p));
        }

        Assert.True(offenders.Count == 0,
            "these open-source projects name the private repository: " + string.Join(", ", offenders)
            + ". The dependency direction is AppBuilder -> Cordango, never the reverse; a public "
            + "clone has no backend/ to resolve against.");
    }

    [Fact]
    public void No_open_source_assembly_references_a_platform_assembly()
    {
        var loaded = AppDomain.CurrentDomain.GetAssemblies()
            .Where(a => (a.GetName().Name ?? "").StartsWith("Cordango.", StringComparison.Ordinal))
            .ToList();

        Assert.NotEmpty(loaded);

