    /// <summary>
    /// The open-source compiler describes the expression language. It does not RUN one.
    ///
    /// <para>The line is the job rather than the feature: the CLI turns an expression into source
    /// code, and the platform turns one into a value. So <c>Cordango.Compiler</c> keeps the grammar,
    /// the parser, the typed AST and the author-time checking — a person has to be told their
    /// expression is wrong whether or not they ever run it here, and a generator in any language needs
    /// the tree to translate. Evaluating belongs to <c>AppBuilder.Runtime.ComputedEval</c>, and so
    /// does everything that will grow around it.</para>
    ///
    /// <para>Asserted rather than remembered, because the natural place to add "just a small helper
    /// that works out what this comes to" is next to the parser, and Apache-2.0 cannot be taken
    /// back once it has shipped.</para>
    /// </summary>
    [Fact]
    public void The_open_source_compiler_parses_expressions_but_does_not_evaluate_them()
    {
        var compiler = AppDomain.CurrentDomain.GetAssemblies()
            .FirstOrDefault(a => a.GetName().Name == "Cordango.Compiler");

        Assert.True(compiler is not null,
            "Cordango.Compiler is not loaded, so this test would pass without checking anything.");

        var expr = compiler!.GetType("Cordango.Definition.ComputedExpr");
        Assert.True(expr is not null, "Cordango.Definition.ComputedExpr has moved or been renamed.");

        // Parsing and static checking are the language, and must stay.
        foreach (var kept in new[] { "Parse", "Validate", "LocalIdentifiers" })
            Assert.True(expr!.GetMethod(kept, BindingFlags.Public | BindingFlags.Static) is not null,
                $"ComputedExpr.{kept} has gone. `cordango check` and every source generator need it.");

        var evaluators = expr!.GetMethods(BindingFlags.Public | BindingFlags.Static)
            .Select(m => m.Name)
            .Where(n => n.StartsWith("Eval", StringComparison.Ordinal))
            .Distinct(StringComparer.Ordinal)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToList();

        Assert.True(evaluators.Count == 0,
            "Cordango.Compiler has grown an expression evaluator again: "
            + string.Join(", ", evaluators)
            + ". The CLI creates source code; the platform executes. Put it in "
            + "AppBuilder.Runtime.ComputedEval instead.");
    }
}

