using System.Text;
using System.Text.Json.Nodes;
using Cordango.Compile;
using Cordango.SourceGen;
using Cordango.SourceGen.DotNetVue;

namespace Cordango.Standalone.Tests;

// THROWAWAY. Dumps generated files to a fixed directory so a refactor can be proved
// byte-identical. Delete after use.
public class ZZDumpTests
{
    [Fact]
    public void Dump()
    {
        var target = Environment.GetEnvironmentVariable("CORDANGO_DUMP_TO")
            ?? throw new InvalidOperationException("set CORDANGO_DUMP_TO");

        var corpus = Path.Combine(TestPaths.RepoRoot(), "tests", "corpus");
        var apps = Directory.GetFiles(Path.Combine(corpus, "reference"), "*.appdef.json")
            .Concat(Directory.GetFiles(corpus, "*.appdef.json"))
            .OrderBy(p => p, StringComparer.Ordinal);

        Directory.CreateDirectory(target);

        foreach (var path in apps)
        {
            var key = Path.GetFileName(path).Replace(".appdef.json", "");
            var definition = JsonNode.Parse(File.ReadAllText(path))!.AsObject();

            var outcome = CandidateValidator.Run(
                definition, key, new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero));
            if (outcome.Manifest is null) { File.WriteAllText(Path.Combine(target, key + ".SKIPPED"), ""); continue; }

            var artifact = new CompiledAppArtifact(
                outcome.Definition!.AsObject(), outcome.Manifest!,
                outcome.Hash ?? "unhashed", new CompilerInfo("test", "1"));

            var result = new DotNetVueGenerator().Generate(new GenerateRequest(artifact, new JsonObject
            {
                ["allowIncomplete"] = true,
                ["seed"] = 42,
            }));

            foreach (var file in result.Files)
            {
                var name = key + "__" + file.RelativePath.Replace('/', '_');
                File.WriteAllBytes(Path.Combine(target, name), new UTF8Encoding(false).GetBytes(file.Content));
            }
        }
    }
}

