<script setup>
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
import { loadRecords, onRecordsChanged, filterTerm, sortTerm } from '../records.js'
import { session } from '../session.js'

// A `repeat` block: the same little layout, once per record. A board of scenario cards, a list of
// funding rounds — shapes a table cannot make because each row is a composition rather than cells.
//
// The children are given the row through a scoped slot named `record`, which shadows whatever
// `record` meant outside. That is deliberate: a field inside a repeat means the repeated record,
// and any other reading would make the same block mean different things in different places.
const props = defineProps({
  entity: String,
  // The definition's own source fragment: which entity, which filters, which order, how many.
  source: { type: Object, default: () => ({}) },
})

const rows = ref([])
const loading = ref(true)
const error = ref(null)

const entityKey = computed(() => props.source?.entity || props.entity)

async function load() {
  if (!entityKey.value) { rows.value = []; loading.value = false; return }
  loading.value = true
  error.value = null
  try {
    const page = await loadRecords(entityKey.value, {
      filters: (props.source?.filters || []).map((f) => filterTerm(f, session)).filter(Boolean),
      sort: (props.source?.sort || []).map(sortTerm).filter(Boolean).join(','),
      take: props.source?.limit ?? 50,
      context: session,
    })
    rows.value = page?.items ?? []
  } catch (failure) {
    error.value = failure.message
    rows.value = []
  } finally {
    loading.value = false
  }
}

let stop
onMounted(() => { load(); stop = onRecordsChanged(entityKey.value, load) })
onUnmounted(() => stop?.())
watch(() => props.source, load, { deep: true })
</script>

<template>
  <v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert>
  <v-skeleton-loader v-else-if="loading" type="list-item-two-line" />
  <div v-else-if="rows.length === 0" class="text-medium-emphasis">Nothing here yet.</div>
  <div v-else class="d-flex flex-column ga-2">
    <template v-for="row in rows" :key="row.id">
      <slot :record="row" />
    </template>
  </div>
</template>
