import json,collections
d=json.load(open(r'C:\Work\github\AppBuilder\oss\cordango\tests\corpus\budget-planner.appdef.json',encoding='utf-8'))
rollups=[]
for e in d['entities']:
    for f in e.get('fields',[]):
        c=f.get('computed')
        if isinstance(c,dict) and 'rollup' in c: rollups.append((e['key'],f['key'],c['rollup']))

# who aggregates whom
edges=collections.defaultdict(set)
for parent,f,r in rollups: edges[parent].add(r['entity'])
print("=== rollup dependency edges (parent <- child) ===")
for p,cs in sorted(edges.items()): print(f"  {p:15} <- {', '.join(sorted(cs))}")

# cycle / depth check
def depth(n, seen=()):
    if n in seen: return 'CYCLE'
    if n not in edges: return 0
    ds=[depth(c, seen+(n,)) for c in edges[n]]
    return 'CYCLE' if 'CYCLE' in ds else 1+max(ds)
print("\n=== depth ===")
for p in sorted(edges): print(f"  {p:15} {depth(p)}")

print("\n=== windowed / matched samples ===")
for p,f,r in rollups:
    if 'window' in r:
        print(f"  {p}.{f} = {json.dumps(r)}")
        break
n=sum(1 for _,_,r in rollups if 'window' in r)
print(f"  ({n} of {len(rollups)} are windowed/matched)")
