import json,glob,collections,os
for path in sorted(glob.glob('tests/corpus/**/*.appdef.json', recursive=True)):
    d=json.load(open(path,encoding='utf-8'))
    edges=collections.defaultdict(set); n=0
    for e in d.get('entities',[]):
        for f in e.get('fields',[]):
            c=f.get('computed')
            if isinstance(c,dict) and 'rollup' in c:
                n+=1; edges[e['key']].add(c['rollup']['entity'])
    if not n: continue
    def depth(x, seen=()):
        if x in seen: return 'CYCLE'
        if x not in edges: return 0
        ds=[depth(c, seen+(x,)) for c in edges[x]]
        return 'CYCLE' if 'CYCLE' in ds else 1+max(ds)
    worst=max((depth(p) for p in edges), key=lambda v: -1 if v=='CYCLE' else v)
    print(f"  {os.path.basename(path):32} rollups={n:3}  depth={worst}")
